CREATE TABLE IF NOT EXISTS studio_configs (tenant_id VARCHAR(36) PRIMARY KEY,revision BIGINT UNSIGNED NOT NULL DEFAULT 0,draft LONGTEXT NOT NULL,published LONGTEXT NOT NULL,published_version BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS studio_versions (tenant_id VARCHAR(36) NOT NULL,version BIGINT UNSIGNED NOT NULL,document LONGTEXT NOT NULL,created_by VARCHAR(36) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS studio_records (tenant_id VARCHAR(36) NOT NULL,module_id VARCHAR(80) NOT NULL,id VARCHAR(36) NOT NULL,project_id VARCHAR(80) NOT NULL,revision BIGINT UNSIGNED NOT NULL,document LONGTEXT NOT NULL,created_by VARCHAR(36) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,module_id,id),INDEX(tenant_id,module_id,project_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS studio_collaboration (tenant_id VARCHAR(36) NOT NULL,id VARCHAR(80) NOT NULL,kind VARCHAR(12) NOT NULL,document LONGTEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),INDEX(tenant_id,kind,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
